with with_gaps as (select *, case when txn_time - lag(txn_time) over (partition by txn_type order by txn_time asc, id asc) > interval '90' day then 1 else 0 end as session_start_flag from transactions), sessions_transactions as (select *, sum(session_start_flag) over (partition by txn_type order by txn_time asc, id asc rows between unbounded preceding and current row) as session_id from with_gaps) select date_trunc('month', txn_time) as activity_month, txn_type, count(distinct id) as distinct_ids, max(txn_time) as last_txn_time from sessions_transactions group by date_trunc('month', txn_time), txn_type
